recipes.code:
{
  "inputs": [
    {
      "id": "scannd-api-key",
      "type": "promptString",
      "description": "Scannd API key (starts with sk_). Sent to the hosted API as the X-API-Key header. Get one at https://scannd.com; the free tier includes 2 scans/month.",
      "password": true
    }
  ],
  "servers": {
    "scannd": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "scannd-mcp@0.1.0"
      ],
      "env": {
        "SCANND_API_KEY": "${input:scannd-api-key}"
      }
    }
  }
}
